; bios.asm -- chapter 30: the BIOS's character set
; generated by gen30.py
        INCLUDE "msx.inc"
        OUTPUT "bios.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
cgtabl  EQU VARS                ; the address read from CGTABL
; The BIOS's 256 shapes, from the address it keeps at $0004 (CGTABL), copied
; into the patterns and shown 16 to a row, from row 4, column 8.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
c0:     ld hl, (CGTABL)         ; where the BIOS keeps its set
        ld (cgtabl), hl         ; kept, for the debugger
        VRAM_WRITE $0000        ; the shapes: 256 characters of 8 bytes
        ld e, 8
        call send               ; 2,048 bytes
c1:     VRAM_WRITE $2000        ; the colours: black on white
        ld a, $1F
        ld e, 8
        call fill
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VDP_REG 1, $C0          ; the display on
done:   jr done

; send: E blocks of 256 bytes from HL to the VDP with OTIR, after an address
; is set: the display is off (chapter 20)
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret

; fill: E blocks of 256 bytes of A to the VDP, after an address is set
fill:   ld b, 0
.out:   out (VDP_DATA), a
        djnz .out
        dec e
        jr nz, .out
        ret
